// Table M_Anggota. PasswordLogin is deliberately not part of this shape.
// NoAnggota is generated by sp_M_Anggota_Insert (YYYY-NNNN); CreatedDate/UpdatedDate have
// no DB default and are set by the procedures.
export interface Anggota {
  NoAnggota: string;
  NoEmployee: string;
  Nama: string;
  Alamat: string | null;
  Telpon: string | null;
  JenisKelamin: string | null;
  DepartmentId: string | null;
  JenisAnggota: string | null;
  TanggalMasuk: string | null; // YYYY-MM-DD
  NoRekening: string | null;
  IsNew: number | null;
  SimpananPokok: number | null;
  SimpananWajib: number | null;
  SimpananSukarela: number | null;
  StatusAnggota: string | null;
  AlamatEmail: string | null;
  CreatedUser: string | null;
  CreatedDate: Date | null;
  UpdatedUser: string | null;
  UpdatedDate: Date | null;
}
